"""Standard Bloom filter and Rational Bloom filter (the paper's RBF).

R1  : the filter is an all-zero bit array of length m (bit packed bytearray).
R4  : an RBF with rational k uses floor(k) always applied hash functions plus
      one probabilistically activated hash function with
      p_activation = k - floor(k)   (Definitions 1 and 2).
R5  : activation is decided by Algorithm 1 line 5,  H_r(x) < p_activation * m,
      with H_r(x) = H_floor(k)(x) ("No additional calculation needed if we,
      e.g., choose Hr(x) = H_floor(k)(x)", Algorithm 1 line 4 comment).
R6  : the identical rule is used for insertion and query, which is what gives
      the RBF its no-false-negative property (Lemma 1).
R7/R8: indices come from Kirsch-Mitzenmacher double hashing with the
      power-of-two AND of Eqn. 3.
R10 : the standard BF baseline shares the very same bit/index/hash path and
      only differs in the number of hash functions (integer k).
"""

import hash_utils as hu


class BaseBloomFilter:
    """All-zero bit array of length m with double-hashed index generation."""

    def __init__(self, m):
        if m <= 0 or (m & (m - 1)) != 0:
            raise ValueError("m must be a positive power of two (Eqn. 3 / R8)")
        self.m = m
        self.mask = m - 1
        self.bits = bytearray((m + 7) // 8)      # R1: empty filter is all zero
        self.set_bits = 0                        # diagnostic counter

    # -- low level bit access -------------------------------------------
    def _get(self, idx):
        return (self.bits[idx >> 3] >> (idx & 7)) & 1

    def _set(self, idx):
        byte, bit = idx >> 3, idx & 7
        if not (self.bits[byte] >> bit) & 1:
            self.bits[byte] |= (1 << bit)
            self.set_bits += 1

    # -- diagnostics ------------------------------------------------------
    def fraction_of_zeros(self):
        return 1.0 - self.set_bits / self.m       # R12 (foz), diagnostic only

    def hash_pairs(self, elements):
        return [hu.hash_pair(x) for x in elements]


class StandardBloomFilter(BaseBloomFilter):
    """k integer hash functions (Section 2, R1)."""

    kind = "BF"

    def __init__(self, m, k):
        super().__init__(m)
        self.k = int(k)
        if self.k < 0:
            raise ValueError("k must be >= 0")

    def _indices(self, h1, h2):
        return [(h1 + i * h2) & self.mask for i in range(self.k)]

    def insert_pair(self, h1, h2):
        for idx in self._indices(h1, h2):          # R1: set the k indices to 1
            self._set(idx)

    def query_pair(self, h1, h2):
        # R1: absent if any index is 0, otherwise present (possible FP)
        for idx in self._indices(h1, h2):
            if not self._get(idx):
                return False
        return True

    def insert(self, x):
        self.insert_pair(*hu.hash_pair(x))

    def query(self, x):
        return self.query_pair(*hu.hash_pair(x))


class RationalBloomFilter(BaseBloomFilter):
    """floor(k) always applied hashes + one hash activated with prob k-floor(k)."""

    kind = "RBF"

    def __init__(self, m, k):
        super().__init__(m)
        self.k = float(k)
        self.floor_k = int(self.k // 1)            # floor, k >= 0
        self.p_activation = self.k - self.floor_k  # R4 / Definition 1
        self.threshold = self.p_activation * m     # R5: p_activation * m
        self.activated_count = 0                   # diagnostics
        self.decided_count = 0

    def _base_indices(self, h1, h2):
        return [(h1 + i * h2) & self.mask for i in range(self.floor_k)]

    def _extra_index(self, h1, h2):
        return (h1 + self.floor_k * h2) & self.mask

    def _hr(self, h1, h2):
        """H_r(x) of Algorithm 1: the last always applied index H_floor(k)(x).

        For floor(k) == 0 there is no always-applied hash function (the RBF is
        only defined with a cost benefit for k > 1, see Section 3); the sweep of
        Figure 6 still covers k < 1, so the degenerate branch uses the first
        hash index H_1(x) as the random value H_r(x) in {0, ..., m-1}.
        """
        if self.floor_k >= 1:
            return (h1 + (self.floor_k - 1) * h2) & self.mask
        return h1 & self.mask

    def _activated(self, h1, h2):
        self.decided_count += 1
        act = self._hr(h1, h2) < self.threshold    # Algorithm 1 line 5 (R5/R6)
        if act:
            self.activated_count += 1
        return act

    def insert_pair(self, h1, h2):
        for idx in self._base_indices(h1, h2):     # Algorithm 1 lines 1-2
            self._set(idx)
        if self._activated(h1, h2):                # Algorithm 1 lines 3-6
            self._set(self._extra_index(h1, h2))

    def query_pair(self, h1, h2):
        for idx in self._base_indices(h1, h2):
            if not self._get(idx):
                return False
        if self._activated(h1, h2):
            return bool(self._get(self._extra_index(h1, h2)))
        return True

    def insert(self, x):
        self.insert_pair(*hu.hash_pair(x))

    def query(self, x):
        return self.query_pair(*hu.hash_pair(x))

    def observed_activation_rate(self):
        if self.decided_count == 0:
            return float("nan")
        return self.activated_count / self.decided_count

